installer-gui-script.script:
function InstallationCheck () {
    if (system.compareVersions(system.version.ProductVersion, "14") < 0
        || system.compareVersions(system.version.ProductVersion, "15.0") >= 0) {
        my.result.message = "This package is meant to be installed on macOS 14.";
        my.result.type = 'Fatal';
        return false;
    }
    if (system.files.fileExistsAtPath('/opt/local/etc/ports/dp_version')) {
        my.result.message = "Your existing MacPorts or DarwinPorts installation is too old to be upgraded by this installer. Please install MacPorts 1.7.1 first.";
        my.result.type = 'Fatal';
        return false;
    }
    if (!system.files.fileExistsAtPath('/usr/bin/xcodebuild')) {
        my.result.message = "Xcode is not installed, or was installed without Command Line Tools or UNIX Development.";
        my.result.type = 'Warn';
        return false;
    }
    return true;
}
